// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.solverimport timber.log.Timberimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.ProblemSolutionimport com.roshan.persona.cognitive.model.RelaxedConstraintimport com.roshan.persona.cognitive.model.SolutionApproachimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Problem Solver (Module 7 v2 — Step 7.6). * * Main entry point for creative problem solving. Combines: *  1. [PatternMatcher] — recall past solutions from Memory. *  2. [ConstraintSatisfier] — check + relax constraints. *  3. Creative synthesis via [PatternMatcher.synthesize]. * * ## Flow (per strategy v2 §"ProblemSolver") * * ``` * 1. Try PATTERN_MATCH — recall past solution from Memory. *    → If found: adapt + check constraints → return. * 2. Try ANALOGY — find similar problem in different domain. *    → If found: adapt + check constraints → return. * 3. Try CREATIVE — synthesize novel solution. *    → If found: check constraints → return. * 4. If no solution satisfies all constraints: *    → Pick least important to relax (per Q4: ask user or auto-relax). *    → Return solution with relaxed constraints + explanation. * 5. If all approaches fail: *    → Return low-confidence fallback solution. * ``` * * ## Approach priority * *  1. PATTERN_MATCH (fast, free, high confidence if match found). *  2. ANALOGY (medium, uses LLM, moderate confidence). *  3. CREATIVE (slow, uses LLM, lower confidence but novel). * * ## Constraint handling (per Q4: ask user) * * When constraints can't all be met: *  - [ConstraintSatisfier.buildRelaxationQuestion] generates a user-facing *    question: "I can't fit everything in ₹15K. Want to increase budget *    or reduce days?" *  - For non-interactive (background): auto-relax least important + explain. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ProblemSolver</a> */class ProblemSolver(    private val patternMatcher: PatternMatcher,    private val constraintSatisfier: ConstraintSatisfier,    private val dispatcher: CoroutineDispatcher,) {    /**     * Solve [problem] within [constraints].     *     * @param problem the user's problem.     * @param constraints the constraints to satisfy.     * @param context additional context (memory, ambient).     * @return a [ProblemSolution] or null if all approaches fail.     */    suspend fun solve(        problem: String,        constraints: List<Constraint> = emptyList(),        context: String = "",    ): ProblemSolution? = withContext(dispatcher) {        Timber.tag(TAG).d("Solving: problem='$problem', constraints=${constraints.size}")        // 1. Try PATTERN_MATCH — recall from Memory.        val patternResult = patternMatcher.matchPattern(problem)        if (patternResult != null) {            val solution = buildSolutionFromPattern(patternResult, constraints)            if (solution != null) return@withContext solution        }        // 2. Try ANALOGY — similar problem in different domain.        val analogyResult = patternMatcher.findAnalogy(problem)        if (analogyResult != null) {            val solution = buildSolutionFromAnalogy(analogyResult, constraints)            if (solution != null) return@withContext solution        }        // 3. Try CREATIVE — synthesize novel solution.        val creativeResult = patternMatcher.synthesize(problem, context)        if (creativeResult != null) {            val solution = buildSolutionFromCreative(creativeResult, constraints)            if (solution != null) return@withContext solution        }        // 4. All approaches failed — return null.        Timber.tag(TAG).w("All problem-solving approaches failed.")        null    }    /**     * Check if a solution satisfies all constraints.     *     * If not, relax the least important violated constraint + return the     * solution with relaxed constraints listed.     */    internal suspend fun buildSolutionFromPattern(        result: PatternMatchResult,        constraints: List<Constraint>,    ): ProblemSolution? {        val violations = constraintSatisfier.checkViolations(result.adaptedSolution, constraints)        val satisfied = constraintSatisfier.checkSatisfaction(result.adaptedSolution, constraints)        val relaxed = mutableListOf<RelaxedConstraint>()        var finalSolution = result.adaptedSolution        // If there are violations, relax the least important.        if (violations.isNotEmpty()) {            val toRelax = constraintSatisfier.pickConstraintToRelax(violations)            if (toRelax != null) {                val relaxation = constraintSatisfier.createRelaxation(                    original = toRelax,                    relaxedValue = "adjusted",                    reason = "Relaxed ${toRelax.type.displayLabel} to fit the solution.",                )                relaxed.add(relaxation)            }        }        return ProblemSolution(            solution = finalSolution,            approach = SolutionApproach.PATTERN_MATCH,            recalledMemory = result.recalledMemory,            constraintsSatisfied = satisfied,            constraintsRelaxed = relaxed,            confidence = result.confidence,        )    }    internal suspend fun buildSolutionFromAnalogy(        result: AnalogicalResult,        constraints: List<Constraint>,    ): ProblemSolution? {        val violations = constraintSatisfier.checkViolations(result.adaptedSolution, constraints)        val satisfied = constraintSatisfier.checkSatisfaction(result.adaptedSolution, constraints)        val relaxed = mutableListOf<RelaxedConstraint>()        if (violations.isNotEmpty()) {            val toRelax = constraintSatisfier.pickConstraintToRelax(violations)            if (toRelax != null) {                relaxed.add(constraintSatisfier.createRelaxation(                    original = toRelax,                    relaxedValue = "adjusted",                    reason = "Relaxed ${toRelax.type.displayLabel} to fit the analogical solution.",                ))            }        }        return ProblemSolution(            solution = result.adaptedSolution,            approach = SolutionApproach.ANALOGY,            recalledMemory = null,  // analogy doesn't come from Memory            constraintsSatisfied = satisfied,            constraintsRelaxed = relaxed,            confidence = result.confidence,        )    }    internal suspend fun buildSolutionFromCreative(        result: CreativeResult,        constraints: List<Constraint>,    ): ProblemSolution? {        val violations = constraintSatisfier.checkViolations(result.solution, constraints)        val satisfied = constraintSatisfier.checkSatisfaction(result.solution, constraints)        val relaxed = mutableListOf<RelaxedConstraint>()        if (violations.isNotEmpty()) {            val toRelax = constraintSatisfier.pickConstraintToRelax(violations)            if (toRelax != null) {                relaxed.add(constraintSatisfier.createRelaxation(                    original = toRelax,                    relaxedValue = "adjusted",                    reason = "Relaxed ${toRelax.type.displayLabel} to fit the creative solution.",                ))            }        }        return ProblemSolution(            solution = result.solution,            approach = SolutionApproach.CREATIVE,            recalledMemory = null,            constraintsSatisfied = satisfied,            constraintsRelaxed = relaxed,            confidence = result.confidence,        )    }    private companion object {        private const val TAG = "ProblemSolver"    }}
